7px 0 -3px #e3b792}.stem:nth-child(3):before{background:#ecd4a2}.stem:after{content:"";position:absolute;top:95px;left:0;width:40px;height:18px;background:#718250;border-radius:0 90% 0 90%;transform:rotate(-25deg)}.facts{display:flex;gap:15px;justify-content:space-between;border-block:1px solid #d5deca;padding:17px 0;font-size:12px;line-height:1.7}.intro{padding-block:35px 24px}.cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;padding-block:15px 25px}.card{background:#eeecde;padding:23px;border-top:2px solid #a76b48}.card p,.policy p,.contact p{font-size:14px;line-height:1.8;color:#53604d}.price{font-weight:bold;font-size:14px}.policy{background:#e9eddf;padding:25px;margin-block:10px 28px}.contact{display:grid;grid-template-columns:1fr 1fr;gap:22px;padding-bottom:30px}.contact section{background:#eeecde;padding:24px}.request label{display:block;font-size:13px;margin:14px 0 5px}.request input{display:block;width:100%;min-width:0;padding:11px;border:1px solid #afbaa3;background:#fffdf5;font:inherit}.request button{margin-top:17px}.quiet{font-size:11px!important;line-height:1.6!important}footer{border-top:1px solid #d5deca;padding-block:22px;font-size:11px;line-height:1.7;color:#53604d;display:flex;justify-content:space-between;gap:20px}@media(max-width:620px){header{align-items:start;flex-direction:column;padding-block:18px}.hero{grid-template-columns:1fr;gap:25px;padding-block:28px}.art{height:270px;width:100%;max-width:360px;margin:auto}h1{font-size:48px}.cards,.contact{grid-template-columns:1fr}.facts,footer{flex-direction:column;gap:7px}.cards{padding-block:10px 24px}.intro{padding-top:25px}}

/* Deliberate delivered defect: service cards overflow a narrow viewport. */
.cards{min-width:760px}

